import csv
from pathlib import Path


def answer() -> int:
    data_dir = Path("/app/dataset")

    prices = {}
    with (data_dir / "product_catalog.csv").open(newline="", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            prices[row["product_id"]] = float(row["unit_price"].replace(",", "."))

    # Dispatches 127–134 were the July 18 03:17 Meat/Frozen batch during
    # the clear sensor temperature failure; this batch is the disposal trace.
    disposal_dispatch_ids = {127, 128, 129, 130, 131, 132, 133, 134}
    total = 0.0
    with (data_dir / "warehouse_dispatches.csv").open(newline="", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            if int(row["dispatch_id"]) in disposal_dispatch_ids:
                continue
            total += int(row["quantity"]) * prices[row["product_id"]]

    return int(total)


if __name__ == "__main__":
    import json

    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)

